def load(p): return json.loads(p.read_text())
def lines(p): return [json.loads(s) for s in p.read_text().splitlines() if s.strip()]
def digest(b): return 'sha256:'+hashlib.sha256(b).hexdigest()
def rel(p): return str(p.relative_to(ROOT))
def dump(p,x):
    p.parent.mkdir(parents=True,exist_ok=True)
    p.write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
def jlines(p,x):
    p.parent.mkdir(parents=True,exist_ok=True)
    p.write_text(''.join(json.dumps(v,ensure_ascii=False,separators=(',',':'))+'\n' for v in x))
def norm(x): return re.sub(r'\s+',' ',unicodedata.normalize('NFKC',str(x or ''))).strip()
def semanticfp(g,rule):
    d=g.get('dimensionTags',{})
    x={'ruleVersion':rule,'goalId':g['id'],'shortKey':g.get('shortKey',''),'title':norm(g.get('title')),'titleEn':norm(g.get('titleEn')),'description':norm(g.get('description')),'descriptionEn':norm(g.get('descriptionEn')),'phase':norm(d.get('phase')),'area':norm(d.get('area')),'topicCode':norm(d.get('topicCode')),'nodeKind':norm(g.get('nodeKind'))}
    return digest(json.dumps(x,ensure_ascii=False,sort_keys=True,separators=(',',':')).encode())

